# owner: platform
import unittest

from hourglass.models import Span
from hourglass.gaps import find_gaps

OPEN = Span(9 * 60, 17 * 60)


class GapTests(unittest.TestCase):
    def test_middle_gap(self):
        worked = [Span(540, 720), Span(780, 1020)]
        self.assertEqual(find_gaps(worked, OPEN), ["gap 12:00-13:00 (60 min)"])

    def test_edges_and_empty(self):
        self.assertEqual(find_gaps([Span(600, 960)], OPEN), [
            "gap 09:00-10:00 (60 min)",
            "gap 16:00-17:00 (60 min)"
        ])
        self.assertEqual(find_gaps([], OPEN), ["gap 09:00-17:00 (480 min)"])

    def test_full_cover(self):
        self.assertEqual(find_gaps([Span(540, 800), Span(800, 1020)], OPEN), [])

    def test_outside_opening_hours(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(480, 600)], OPEN)
